/** 🌳️ Round-3 small-leaved lime (Tilia cordata, park tree of about 60 years): every stem and limb section, branch, burr, ridge, shoot, leaf lobe, tuft and outlet is stated by hand per scale in world metres (x ahead, y up, z lateral) and written as bone-local solids to `volumes/vegetation/small-leaved-lime.json`; the root fixes (lateral bone offsets, emitter anchors, bark areas, symbols, 2D drawings as true views of each scale's body) go to the candidate document `🗑️generated/r3-small-leaved-lime/🔣️.json`.
 * @see ./round3-brief.md
 * @see ./r3-vegetation-small-leaved-lime.md */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { GENERATED, SOURCES, entryOf, frames, toLocal, type Frame, type Json, type V3 } from "./volumes-lib.ts";
import { D2R, add, along, branch, dirOf, dot3, mul, r4, r5, ringLobe, solidOf, sub, surfacePoint, unit, type Lobe, type Part, type Tube } from "./r3-small-leaved-lime-kit.ts";
import { draw, drawSymbols } from "./r3-small-leaved-lime-draw.ts";

const { entry } = entryOf("vegetation/small-leaved-lime");
const document: Json = JSON.parse(readFileSync(entry.path, "utf8"));
const asset: Json = document.asset;
const bone = (id: string): Json => asset.rig.bones.find((b: Json) => b.id === id);

export const LIMBS = {
  w1: { az: 195, a: "lw1a", b: "lw1b", fol: "fol-w1" }, e1: { az: 15, a: "le1a", b: "le1b", fol: "fol-e1" },
  w2: { az: 150, a: "lw2a", b: null, fol: "fol-w2" }, e2: { az: 330, a: "le2a", b: null, fol: "fol-e2" },
  w3: { az: 210, a: "lw3a", b: null, fol: "fol-w3" }, e3: { az: 30, a: "le3a", b: null, fol: "fol-e3" },
  w4: { az: 160, a: "lw4a", b: null, fol: "fol-w4" }, e4: { az: 340, a: "le4a", b: null, fol: "fol-e4" },
} as const;
type LimbKey = keyof typeof LIMBS;

for (const b of asset.rig.bones) delete b.z;
const planar = frames(asset);
const lateral = (limb: LimbKey, x: number): number => (x - planar[LIMBS[limb].a]!.o[0]) * Math.tan(LIMBS[limb].az * D2R);
const absoluteZ: Record<string, number> = {};
for (const [key, l] of Object.entries(LIMBS) as [LimbKey, (typeof LIMBS)[LimbKey]][]) {
  if (l.b) absoluteZ[l.b] = lateral(key, planar[l.b]!.o[0]);
  absoluteZ[l.fol] = lateral(key, planar[l.fol]!.o[0]);
}
for (const b of asset.rig.bones) if (absoluteZ[b.id] !== undefined) b.z = r4(absoluteZ[b.id]! - (absoluteZ[b.parent] ?? 0));
const F: Record<string, Frame> = frames(asset);

const BARK = "lime-bark", YOUNG = "lime-bark-young", TWIG = "lime-twig", SUN = "lime-leaf-sun", SHADE = "lime-leaf-shade", EPI = "lime-leaf-epicormic", WOOD = "lime-wood";
const TONE = { root: 0.3, stem: 0.36, limb: 0.38, twig: 0.38, ridge: 0.15, sun: 0.6, shade: 0.45, epi: 0.5 };

/** 📏️ The x of the stem axis at the height y (the rig's leader joints). */
const AXIS: [number, number][] = [[0, 0], [2.9, 0], [6.2, -0.029], [9.6, 0.031], [12.6, -0.022], [14.2, -0.022]];
export function sx(y: number): number {
  for (let i = 0; i + 1 < AXIS.length; i++) if (y <= AXIS[i + 1]![0]) return AXIS[i]![1] + ((AXIS[i + 1]![1] - AXIS[i]![1]) * (y - AXIS[i]![0])) / (AXIS[i + 1]![0] - AXIS[i]![0]);
  return AXIS[AXIS.length - 1]![1];
}

/** 🪵️ A stem part on the stem axis: rows [height y, radius, x offset, z offset]. */
const stem = (id: string, material: string, tone: number, group: string, rows: [number, number, number, number][]): Tube => ({ kind: "tube", id, bone: id, material, tone, group, points: rows.map(([y, r, dx, dz]) => ({ p: [sx(y) + dx, y, dz] as V3, r })) });

/** 🌿️ A rig limb part: rows [u along the bone, bow upwards, radius]; the lateral position follows the limb's azimuth. */
function scaffold(limb: LimbKey, part: "a" | "b", rows: [number, number, number][]): Tube {
  const id = LIMBS[limb][part]!;
  const f = planar[id]!;
  const up: V3 = f.v[1] > 0 ? f.v : mul(f.v, -1);
  return {
    kind: "tube", id, bone: id, material: YOUNG, tone: TONE.limb, group: "limb",
    points: rows.map(([u, bow, r]) => {
      const p = add(add(f.o, mul(f.u, u)), mul(up, bow));
      return { p: [p[0], p[1], lateral(limb, p[0])] as V3, r };
    }),
  };
}

