const ENV = (az: number): number => 1 / Math.hypot(Math.cos(az * D2R) / 4.5025, Math.sin(az * D2R) / 4.4735);
/** 🥚️ The crown profile: share of the widest radius at the height y (widest at 6.5 m, hanging skirt below, blunt ovoid top above). */
export const dome = (y: number): number => (y >= 6.5 ? Math.max(0, 1 - ((y - 6.5) / 7.75) ** 2.3) ** 0.55 : Math.sqrt(Math.max(0, 1 - ((6.5 - y) / 4.6) ** 2)));

