/** 🧭️ The azimuths of the foliage masses the front and plan drawings bind to each bone, per tier; a lobe belongs to the nearest one. */
const SECTORS: Record<number, Record<number, number[]>> = {
  50: { 1: [0, 45, 90, 135, 180, 225, 270, 315], 2: [0, 45, 90, 135, 180, 225, 270, 315], 3: [0, 90, 180, 270], 4: [0, 90, 180, 270] },
  100: { 1: [0, 90, 180, 270], 2: [0, 45, 90, 135, 180, 225, 270, 315], 3: [0, 90, 180, 270], 4: [0, 90, 180, 270] },
  200: { 1: [0, 90, 180, 270], 2: [0, 90, 180, 270], 3: [0, 90, 180, 270], 4: [0, 180] },
};
const eastOf = (sector: number): boolean => sector === 0 || sector === 45 || sector === 90 || sector === 315;
export const sectorOf = (scale: number, tier: number, az: number): number => {
  const list = SECTORS[scale]![tier]!;
  const gap = (s: number): number => Math.abs(((az - s + 540) % 360) - 180);
  return list.reduce((best, s) => (gap(s) < gap(best) - 1e-9 ? s : best), list[0]!);
};

export type CrownLobe = Lobe & { tier: number; sector: number; ring: string; main: boolean };

function crown(scale: number): CrownLobe[] {
  const rings = scale === 200 ? RINGS_200 : scale === 500 ? RINGS_500 : RINGS_50;
  const swell: V3 = scale === 100 ? SWELL_100 : [0, 0, 0];
  const out: CrownLobe[] = [];
  const byRing: Record<string, CrownLobe[]> = {};
  for (const ring of rings) {
    byRing[ring.id] = [];
    ring.lobes.forEach(([az, k, dy, s, wide = 1, tall = 1], i) => {
      const y = ring.y + dy;
      const sector = scale === 500 || ring.tier === 5 ? 0 : sectorOf(scale, ring.tier, az);
      const b = scale === 500 ? "ld1" : ring.tier === 5 ? "fol-top" : `fol-${eastOf(sector) ? "e" : "w"}${ring.tier}`;
      const id = scale === 500 ? `crown-${ring.id}${i + 1}` : `${b}-${ring.id}${i + 1}`;
      const l = ringLobe(id, b, SUN, TONE.sun, "sun", az, ENV(az) * dome(y) * k, y, ring.a * s + swell[0], ring.b * s * tall + swell[1], ring.c * s * wide + swell[2], ring.tilt, sx(y));
      const lobe: CrownLobe = { ...l, tier: ring.tier, sector, ring: ring.id, main: true };
      out.push(lobe);
      byRing[ring.id]!.push(lobe);
    });
  }
  const [ty, ta, tb, tc] = TOP[scale]!;
  out.push({ kind: "lobe", id: scale === 500 ? "crown-top" : "fol-top-cap", bone: scale === 500 ? "ld1" : "fol-top", material: SUN, tone: TONE.sun, group: "sun", c: [sx(ty), ty, 0], axes: [[1, 0, 0], [0, 1, 0], [0, 0, 1]], radii: [ta, tb, tc], tier: 5, sector: 0, ring: "top", main: true });
  if (scale === 50) for (const [ringId, n, dAz, el, r] of TUFTS_50) {
    const parent = byRing[ringId]![n - 1];
    if (!parent) throw new Error(`tuft on unknown lobe ${ringId}${n}`);
    const az = (Math.atan2(parent.c[2], parent.c[0] - sx(parent.c[1])) * 180) / Math.PI + dAz;
    const d = dirOf(az, el);
    const free = sub(surfacePoint(parent, d), mul(d, r - 0.09));
    const [hx, hz] = [free[0] - sx(free[1]), free[2]];
    const far = Math.hypot(hx, hz);
    const most = ENV((Math.atan2(hz, hx) * 180) / Math.PI) - r * 1.1 - 0.005;
    const c: V3 = far > most ? [sx(free[1]) + (hx * most) / far, free[1], (hz * most) / far] : free;
    out.push({ kind: "lobe", id: `${parent.id}-t`, bone: parent.bone, material: SUN, tone: TONE.sun, group: "sun", c, axes: [[1, 0, 0], [0, 1, 0], [0, 0, 1]], radii: [r, r * 0.9, r * 1.1], tier: parent.tier, sector: parent.sector, ring: parent.ring, main: false });
  }
  for (const [id, b, az, reach, y, a, bb, c] of SHADE_LOBES[scale]!) {
    const l = ringLobe(id, b, SHADE, TONE.shade, "shade", az, reach, y, a, bb, c, 0, sx(y));
    out.push({ ...l, tier: 0, sector: 0, ring: "shade", main: true });
  }
  for (const [id, b, c, radii, turn = 0] of EPI_LOBES[scale]!) out.push({ kind: "lobe", id, bone: b, material: EPI, tone: TONE.epi, group: "epi", c, axes: [[Math.cos(turn * D2R), Math.sin(turn * D2R), 0], [-Math.sin(turn * D2R), Math.cos(turn * D2R), 0], [0, 0, 1]], radii, tier: 0, sector: 0, ring: "epi", main: true });
  return out;
}

const interpolate = (rows: StemRows, y: number): [number, number, number] => {
  for (let i = 0; i + 1 < rows.length; i++) if (y <= rows[i + 1]![0]) {
    const t = Math.max(0, (y - rows[i]![0]) / (rows[i + 1]![0] - rows[i]![0]));
    return [rows[i]![1] + (rows[i + 1]![1] - rows[i]![1]) * t, rows[i]![2] + (rows[i + 1]![2] - rows[i]![2]) * t, rows[i]![3] + (rows[i + 1]![3] - rows[i]![3]) * t];
  }
  const last = rows[rows.length - 1]!;
  return [last[1], last[2], last[3]];
};

function woody(scale: number): { wood: Tube[]; ridges: Tube[]; shoots: Tube[]; burrs: Lobe[] } {
  const wood: Tube[] = [];
  for (const [id, rows] of Object.entries(STEMS[scale]!)) wood.push(stem(id, STEM_LOOK[id]![0], STEM_LOOK[id]![1], STEM_LOOK[id]![2], rows));
  const buttress = scale === 50 ? BUTTRESS_50 : scale === 100 ? BUTTRESS_100 : [];
  buttress.forEach(([az, k], i) => {
    const d = (r: number, y: number): V3 => [r * k * Math.cos(az * D2R), y, r * k * Math.sin(az * D2R)];
    const points = scale === 50
      ? [{ p: d(0.25, 0.86), r: 0.05 }, { p: d(0.27, 0.62), r: 0.085 }, { p: d(0.32, 0.42), r: 0.11 }, { p: d(0.4, 0.27), r: 0.118 }, { p: d(0.51, 0.16), r: 0.105 }, { p: d(0.63, 0.09), r: 0.078 }, { p: d(0.74, 0.052), r: 0.05 }, { p: d(0.82, 0.03), r: 0.028 }, { p: d(0.86, 0.016), r: 0.014 }]
      : [{ p: d(0.26, 0.84), r: 0.05 }, { p: d(0.31, 0.45), r: 0.108 }, { p: d(0.5, 0.165), r: 0.105 }, { p: d(0.73, 0.055), r: 0.05 }, { p: d(0.85, 0.02), r: 0.018 }];
    wood.push({ kind: "tube", id: `root-${i + 1}`, bone: "root-plate", material: BARK, tone: TONE.root, group: "root", points });
  });
  const table = scale === 50 ? SCAFFOLD_50 : scale === 100 ? SCAFFOLD_100 : scale === 200 ? SCAFFOLD_200 : SCAFFOLD_500;
  for (const [limb, part, rows] of table) wood.push(scaffold(limb, part, rows));
  const free = scale === 50 ? FREE_50 : scale === 100 ? FREE_100 : scale === 200 ? FREE_200 : FREE_500;
  for (const [id, b, y, az, e0, e1, L, r0, r1, bend] of free) wood.push(branch(id, b, YOUNG, TONE.limb, "free", [sx(y), y, 0], az, e0, e1, L, r0, r1, bend, scale === 50 ? 7 : scale === 100 ? 4 : scale === 200 ? 3 : 2));
  const byId = (id: string): Tube => wood.find((t) => t.id === id)!;
  if (scale === 50) for (const [id, parent, f, az, e0, e1, L, r0, r1, bend] of SIDES_50) wood.push(branch(id, byId(parent).bone, YOUNG, TONE.limb, "side", along(byId(parent), f), az, e0, e1, L, r0, r1, bend, 5));
  const trunkRows = STEMS[scale]!.trunk!;
  const ridges: Tube[] = [];
  const ridgeTable = scale === 50 ? RIDGES_50 : scale === 100 ? RIDGES_100 : [];
  ridgeTable.forEach(([az, wander], i) => {
    const n = wander.length;
    const points = wander.map((dAz, k) => {
      const y = 0.56 + ((2.82 - 0.56) * k) / (n - 1);
      const [r, dx, dz] = interpolate(trunkRows, y);
      const a = (az + dAz) * D2R;
      const end = k === 0 || k === n - 1;
      const out = end ? r - 0.004 : r + 0.003;
      return { p: [sx(y) + dx + out * Math.cos(a), y, dz + out * Math.sin(a)] as V3, r: end ? 0.006 : scale === 50 ? 0.011 : 0.012 };
    });
    ridges.push({ kind: "tube", id: `ridge-${i + 1}`, bone: "trunk", material: BARK, tone: TONE.ridge, group: "ridge", points, flags: { slender: true, texture: true } });
  });
  const shoots: Tube[] = SHOOTS[scale]!.map(([id, b, rows]) => {
    const f = F[b]!;
    return { kind: "tube", id, bone: b, material: TWIG, tone: TONE.twig, group: "epi", points: rows.map(([u, v, w, r]) => ({ p: add(add(add(f.o, mul(f.u, u)), mul(f.v, v)), mul(f.w, w)), r })), ...(scale === 500 ? { flags: { slender: true } } : {}) };
  });
  const burrs: Lobe[] = BURRS[scale]!.map(([id, az, y, a, b, c]) => {
    const [r, dx, dz] = interpolate(trunkRows, y);
    const rad: V3 = [Math.cos(az * D2R), 0, Math.sin(az * D2R)];
    return { kind: "lobe", id, bone: "trunk", material: BARK, tone: TONE.stem, group: "burr", c: [sx(y) + dx + (r - 0.012) * rad[0], y, dz + (r - 0.012) * rad[2]], axes: [rad, [0, 1, 0], [-rad[2], 0, rad[0]]], radii: [a, b, c] };
  });
  return { wood, ridges, shoots, burrs };
}

