export type Model = { scale: number; wood: Tube[]; ridges: Tube[]; shoots: Tube[]; burrs: Lobe[]; hiddenWood: Tube[]; hiddenShoots: Tube[]; lobes: CrownLobe[]; outlets: Outlet[]; decisions: { en: string; de: string }[] };

function model(scale: number): Model {
  const { wood, ridges, shoots, burrs } = woody(scale);
  const hide = (t: Tube): boolean => {
    if (scale === 500) return !["root-plate", "trunk"].includes(t.id);
    if (scale === 200) return ["ld4", "lw4a", "le4a"].includes(t.id);
    return false;
  };
  return { scale, wood: wood.filter((t) => !hide(t)), ridges, shoots: scale === 500 ? [] : shoots, burrs, hiddenWood: wood.filter(hide), hiddenShoots: scale === 500 ? shoots : [], lobes: crown(scale), outlets: OUTLETS[scale]!, decisions: DECISIONS[scale]! };
}

const anchorsOut: Record<string, { bone: string; local: V3 }> = {};
const regionOf = (p: Part): string => {
  if (p.kind === "lobe") return p.group === "shade" ? "leaf-shade" : p.group === "epi" ? "leaf-epicormic" : p.group === "burr" ? "trunk-bark" : "leaf-sun";
  if (p.group === "epi") return "epicormic-stem";
  return p.group === "root" || p.group === "stem" ? "trunk-bark" : "limb-bark";
};

function volumeOf(m: Model): Json {
  const s = (p: Part): Json => solidOf(p, F);
  const body: Json[] = [...m.wood.map(s), ...m.burrs.map(s), ...m.ridges.map(s), ...m.shoots.map(s), ...m.lobes.map((l) => s(l))];
  const thermal: Json[] = [];
  for (const p of [...m.wood, ...m.burrs, ...m.shoots, ...m.lobes] as Part[]) thermal.push({ id: `th-${p.id}`, of: p.id, region: regionOf(p) });
  for (const p of [...m.hiddenWood, ...m.hiddenShoots]) thermal.push({ ...s({ ...p, id: `th-${p.id}` }), region: regionOf(p) });
  m.outlets.forEach(([emitter, anchor, lobeId, az, el], i) => {
    const l = m.lobes.find((x) => x.id === lobeId);
    if (!l) throw new Error(`1:${m.scale} outlet on unknown lobe ${lobeId}`);
    const d = dirOf(az, el);
    const p = surfacePoint(l, d);
    const q = sub(p, l.c);
    const n = unit(l.axes.reduce((sum, axis, k) => add(sum, mul(axis, dot3(q, axis) / l.radii[k]! ** 2)), [0, 0, 0] as V3));
    const side = unit(Math.abs(n[1]) > 0.98 ? [n[1], -n[0], 0] : [n[2], 0, -n[0]]);
    const third: V3 = [side[1] * n[2] - side[2] * n[1], side[2] * n[0] - side[0] * n[2], side[0] * n[1] - side[1] * n[0]];
    const rho = Math.min(l.radii[0], l.radii[2]) * (m.scale === 500 ? 0.45 : 0.6);
    const h = Math.max(0.1, (0.15 * m.scale) / 1000, ((rho * rho) / (2 * Math.min(...l.radii))) * 0.8);
    const lens: Lobe = { kind: "lobe", id: `th-${anchor ?? `${emitter}-${i + 1}`}`, bone: l.bone, material: l.material, tone: l.tone, group: l.group, c: sub(p, mul(n, h - 0.02)), axes: [side, n, third], radii: [rho, h, rho] };
    thermal.push({ ...s(lens), role: "detail", region: regionOf(l), tags: [emitter] });
    const out = add(p, mul(n, 0.03));
    const buried = m.lobes.find((o) => o !== l && Math.hypot(...o.axes.map((axis, k) => dot3(sub(out, o.c), axis) / o.radii[k]!)) < 1);
    if (buried && l.group !== "shade") console.log(`[DEBUG] 1:${m.scale} outlet on ${lobeId} is buried in ${buried.id}`);
    if (anchor) anchorsOut[anchor] = { bone: l.bone, local: toLocal(F[l.bone]!, add(p, mul(n, 0.04))) };
  });
  const structure: Json[] = [];
  const feature = (0.15 * m.scale) / 1000;
  const bark = (r: number): number => 0.002 + 0.04 * r;
  const members = [...m.wood, ...m.hiddenWood, ...m.shoots, ...m.hiddenShoots].filter((t) => t.id === t.bone || t.group === "free");
  for (const t of members) {
    const rigged = t.id === t.bone;
    const declared = rigged ? Math.sqrt(bone(t.bone).section.areaM2 / Math.PI) : 0;
    const pts = m.scale === 500 && rigged && t.group !== "root" ? t.points.map((q) => ({ p: q.p, r: declared })) : t.points.map((q) => ({ p: q.p, r: t.group === "epi" ? Math.max(q.r - bark(q.r), feature / 2 + 0.0003) : q.r - bark(q.r) }));
    structure.push({ ...s({ ...t, id: `member-${t.id}`, material: WOOD, tone: 0.4, points: pts, flags: t.group === "epi" && m.scale === 500 ? { slender: true } : undefined } as Tube), member: t.bone, part: "member" });
  }
  for (const t of members) {
    if (t.bone === "root-plate" || t.id !== t.bone) continue;
    const f = F[t.bone]!;
    const first = t.points.find((q) => toLocal(f, q.p)[0] >= -1e-6) ?? t.points[0]!;
    const r = (first.r - bark(first.r)) * 1.12;
    if (2 * r < feature || (m.scale === 500 && !["trunk", "ld1", "ld2", "ld3"].includes(t.bone))) continue;
    structure.push({ id: `joint-${t.bone}`, kind: "ellipsoid", bone: t.bone, material: WOOD, role: "detail", tone: 0.35, radii: [r5(r), r5(r), r5(r)], transform: { translation: [0, 0, 0] }, member: t.bone, part: "joint" });
  }
  const plate = Math.max(0.05, feature);
  structure.push({ id: "support-base-support", kind: "revolve", bone: "root-plate", material: WOOD, role: "detail", tone: 0.25, profile: [[r5(-plate), 1], [0, 1]], axis: [1, 0, 0], origin: [0, 0, 0], member: "root-plate", part: "support", anchor: "base-support" });
  const masses: [string, number, number, number][] = [["root-plate", 0.14, 0.2, 0.2], ["trunk", 0.32, 0.16, 0.16], ["ld1", 0.3, 0.13, 0.13], ["ld2", 0.26, 0.09, 0.09]];
  for (const [id, a, b, c] of masses) structure.push({ id: `mass-${id}`, kind: "ellipsoid", bone: id, material: WOOD, role: "detail", tone: 0.3, radii: [a, b, c], transform: { translation: [bone(id).mass.comX, bone(id).mass.comY, 0] }, member: id, part: "mass" });
  if (m.scale !== 500) for (const b of asset.rig.bones.filter((x: Json) => x.id.startsWith("fol-"))) {
    const r = Math.max(feature * 0.6, Math.cbrt((3 * b.mass.kg) / (4 * Math.PI * 800)));
    const material = b.id.startsWith("fol-core") ? SHADE : b.id.startsWith("fol-epi") ? EPI : SUN;
    structure.push({ id: `mass-${b.id}`, kind: "ellipsoid", bone: b.id, material, role: "detail", tone: 0.3, radii: [r5(r), r5(r), r5(r)], transform: { translation: [b.mass.comX, b.mass.comY, 0] }, member: b.parent, part: "mass" });
  }
  return { status: "authored", denominator: m.scale, body, thermal, structure, decisions: m.decisions };
}

export const models = [50, 100, 200, 500].map(model);
for (const m of models) for (const t of [...m.wood, ...m.hiddenWood, ...m.shoots]) {
  if (!["limb", "free", "side", "epi"].includes(t.group) || /^ld\d$|^l[we]1a$/.test(t.id)) continue;
  const tip = t.points[t.points.length - 1]!.p;
  const depth = Math.max(...m.lobes.map((l) => 1 - Math.hypot(...l.axes.map((a, i) => (a[0] * (tip[0] - l.c[0]) + a[1] * (tip[1] - l.c[1]) + a[2] * (tip[2] - l.c[2])) / l.radii[i]!))));
  if (depth < 0.06) console.log(`[DEBUG] 1:${m.scale} tip of ${t.id} at ${tip.map((v) => v.toFixed(2)).join(" ")} is ${depth < 0 ? "outside" : "shallow in"} the foliage (${depth.toFixed(2)})`);
}
const volumes: Json = {};
for (const m of models) volumes[String(m.scale)] = volumeOf(m);

if (import.meta.main) {
  writeFileSync(join(SOURCES, "vegetation", "small-leaved-lime.json"), JSON.stringify({ volumes }) + "\n");
  for (const a of asset.anchors) {
    const moved = anchorsOut[a.id];
    if (!moved) continue;
    if (moved.bone !== a.bone) throw new Error(`anchor ${a.id} would change its bone from ${a.bone} to ${moved.bone}`);
    a.x = r4(moved.local[0]);
    a.y = r4(moved.local[1]);
    a.z = r4(moved.local[2]);
  }
  const AREAS: Record<string, number> = JSON.parse(readFileSync(join(import.meta.dir, "r3-small-leaved-lime-areas.json"), "utf8"));
  for (const region of asset.thermal.regions) if (AREAS[region.id] !== undefined) region.areaM2 = AREAS[region.id];
  asset.volumes = volumes;
  const report = [...draw(asset, F, models), ...drawSymbols(asset, models)];
  const out = join(GENERATED, "r3-small-leaved-lime");
  mkdirSync(out, { recursive: true });
  writeFileSync(join(out, "🔣️.json"), JSON.stringify(document, null, 2) + "\n");
  for (const m of models) console.log(`1:${m.scale} body ${volumes[m.scale].body.length} thermal ${volumes[m.scale].thermal.length} structure ${volumes[m.scale].structure.length}`);
  console.log(report.join("\n"));
}
for (const m of models) {
  const far = (e: V3, sign: number): { v: number; id: string } => m.lobes.map((l) => ({ v: sign * dot3(l.c, e) + Math.hypot(...l.axes.map((a, i) => l.radii[i]! * dot3(a, e))), id: l.id })).sort((a, b) => b.v - a.v)[0]!;
  const show = (e: V3, sign: number): string => `${far(e, sign).v.toFixed(3)} ${far(e, sign).id}`;
  console.log(`[DEBUG] 1:${m.scale} extents +x ${show([1, 0, 0], 1)} -x ${show([1, 0, 0], -1)} +z ${show([0, 0, 1], 1)} -z ${show([0, 0, 1], -1)} top ${show([0, 1, 0], 1)}`);
}
